bool isConsecutive(vector<int> &nums)
{
    int n = nums.size();
    int minNum = INT_MAX;

    for (int i = 0; i < n; i++)
    {
        minNum = min(minNum, nums[i]);
    }

    cout<<"size: "<<(minNum - n) + 1<<endl<<"nums length: "<<n<<endl<<"minimum number: "<<minNum<<endl;

    vector<int> hash((minNum - n) + 1, 0);
    for (int i = 0; i < n; i++)
    {
        hash[nums[i] - minNum]++;
    }

    for (int i = 0; i < hash.size(); i++)
    {
        if (hash[i] != 1)
            return false;
    }

    return true;
}

